# -*- coding: utf-8 -*-
# 第二卷·第三部（26 章）提案
NOTES = {
    "2-3-01": {"gist": "1809年春，蛰居两年的安德烈在保古察罗伏办农政有成；赴梁赞视察庄园途中遇一棵拒绝春天的老栎树，自谓人生已尽。", "tag": "peace", "place": "梁赞", "chars": ["andrei"], "year": 1809},
    "2-3-02": {"gist": "安德烈到奥特拉德诺耶找县首席贵族罗斯托夫伯爵办事，被强留过夜；月夜窗前听见娜塔莎无眠的歌唱与赞叹。", "tag": "peace", "place": "奥特拉德诺耶", "chars": ["andrei", "ilya", "natasha", "sophia"], "year": 1809, "month": 5},
    "2-3-03": {"gist": "归途再见老栎树已换新绿，安德烈顿感重生，决计秋天去彼得堡；独处时对镜沉思，对妹妹玛丽雅变得冷硬。", "tag": "peace", "place": "保古察罗伏", "chars": ["andrei", "marya"], "year": 1809, "month": 6},
    "2-3-04": {"gist": "1809年8月安德烈到彼得堡，正值斯佩兰斯基改革鼎盛；他呈上军事条令意见书，被阿拉克切耶夫冷斥为无须另立新章。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "speransky", "arakcheev", "alexander"], "year": 1809, "month": 8},
    "2-3-05": {"gist": "柯楚别依家的客厅里，安德烈初见斯佩兰斯基，就贵族特权与荣誉之争各执一词；斯佩兰斯基邀他周三过谈并引荐条令委员会主席。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "speransky", "arakcheev"], "year": 1809},
    "2-3-06": {"gist": "安德烈周三与斯佩兰斯基推心置腹长谈，如当年拜服拿破仑般倾慕其理性；一周后进条令委员会任编纂处长，起草人权条文。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "speransky", "napoleon"], "year": 1809},
    "2-3-07": {"gist": "皮埃尔成了彼得堡共济会核心，自国外回来后在二级大会上演说主张入世行动，被疑为光明会，与会友激烈争论后拂袖而去。", "tag": "peace", "place": "彼得堡", "chars": ["pierre", "bazdeev", "villarsky"], "year": 1809},
    "2-3-08": {"gist": "演说受挫后皮埃尔忧郁症发作，仍赴莫斯科求教巴兹杰耶夫；归来接纳海伦复婚，自谓背起十字架，搬进大宅楼上。", "tag": "peace", "place": "莫斯科", "chars": ["pierre", "bazdeev", "helen", "kuragina"], "year": 1809, "month": 11},
    "2-3-09": {"gist": "海伦携皮埃尔回彼得堡，以「聪明美丽的迷娘」名头主持沙龙；得势的保里斯成了常客，皮埃尔厌恶却又自缚，不敢猜疑。", "tag": "peace", "place": "彼得堡", "chars": ["pierre", "helen", "boris", "napoleon"], "year": 1809},
    "2-3-10": {"gist": "皮埃尔日记：他主持把保里斯接纳入会并充任导师，憎恨与自责交缠；接连的怪梦与巴兹杰耶夫来信提醒他尽夫妻义务。", "tag": "peace", "place": "彼得堡", "chars": ["pierre", "boris", "bazdeev"], "year": 1809},
    "2-3-11": {"gist": "罗斯托夫家破产般迁居彼得堡，别尔格向薇拉求婚成功，订婚月余又逼问陪嫁，老伯爵应下八万期票外加两万现款。", "tag": "peace", "place": "彼得堡", "chars": ["ilya", "vera", "berg", "countess_r"], "year": 1809},
    "2-3-12": {"gist": "十六岁的娜塔莎在彼得堡再遇童年情人保里斯；他盘算娶富女却日日登门，两人谁也没提四年前的旧约。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "boris", "countess_r", "sophia"], "year": 1809},
    "2-3-13": {"gist": "除夕前夜娜塔莎钻进母亲被窝谈保里斯，说自己绝对不出嫁也要他来；伯爵夫人次日找保里斯摊牌，他从此不再登门。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "countess_r", "boris", "ilya"]},
    "2-3-14": {"gist": "1809年12月31日除夕迎新大舞会之夜，第一次赴宴的娜塔莎整天张罗母女三人梳妆，缝裙别帽，迟到才动身去公馆。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "sophia", "countess_r", "ilya"], "year": 1809, "month": 12},
    "2-3-15": {"gist": "罗斯托夫家踏入灯火通明的舞厅，彼隆斯卡雅指点全场名流：海伦、阿纳托里、皮埃尔，还有穿白军服重获新生的安德烈。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "sophia", "countess_r", "pierre", "helen", "anatole", "andrei"]},
    "2-3-16": {"gist": "波兰舞轮空，娜塔莎几乎落泪；皮埃尔拉安德烈请她跳华尔兹，两人第二对入场，安德烈被这初次亮相的少女迷住。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "andrei", "pierre", "helen", "sophia"]},
    "2-3-17": {"gist": "科季里昂舞中安德烈向娜塔莎提起奥特拉德诺月夜，脱口想过「她将成为我的妻子」；娜塔莎幸福到顶点，独皮埃尔的闷郁令她不解。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "andrei", "boris", "ilya", "pierre"]},
    "2-3-18": {"gist": "次日安德烈对国务会议已觉索然；在斯佩兰斯基家晚宴上，做作的笑声与清谈使他幻灭，回望四个月奔走只剩惭愧。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "speransky", "berg"]},
    "2-3-19": {"gist": "安德烈再访罗斯托夫家，听娜塔莎唱歌时没来由落泪；当夜失眠却畅快，盘算退役出国、认真安排儿子的教育。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "natasha", "ilya"]},
    "2-3-20": {"gist": "别尔格乔迁后办小型晚会，拉皮埃尔撑场面；夫妇俩争先待客，处处模仿名门规格，只求一切同别人家一样。", "tag": "peace", "place": "彼得堡", "chars": ["berg", "vera", "pierre", "boris"]},
    "2-3-21": {"gist": "别尔格晚会上娜塔莎恹恹无光，安德烈一进门她便重焕神采；薇拉笨拙地试探婚事，安德烈窘迫地坐到娜塔莎身边低声问询。", "tag": "peace", "place": "彼得堡", "chars": ["natasha", "andrei", "pierre", "vera", "boris"]},
    "2-3-22": {"gist": "安德烈在罗斯托夫家纠缠整日；深夜向皮埃尔坦白恋爱与娶娜塔莎的决心，皮埃尔强抑忧郁连声劝婚，越为他高兴越觉得自己暗淡。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "natasha", "pierre", "countess_r", "sophia"]},
    "2-3-23": {"gist": "老公爵有条件地放行：婚期推迟一年。三周后安德烈回彼得堡正式求婚，娜塔莎又惊又喜，唯独害怕那漫长的一年。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "old_prince", "natasha", "countess_r", "sophia"]},
    "2-3-24": {"gist": "秘密订婚期间安德烈天天出入罗斯托夫家；临行前他把娜塔莎托给皮埃尔，告别后娜塔莎麻木数日，两周后才恢复旧观。", "tag": "peace", "place": "彼得堡", "chars": ["andrei", "natasha", "pierre", "ilya", "countess_r", "sophia"]},
    "2-3-25": {"gist": "安德烈出国一年间，老公爵在童山愈发乖戾，专拿信仰与孩子折磨玛丽雅；她写信安慰丧兄的裘丽，把一切归于上帝旨意。", "tag": "peace", "place": "童山", "chars": ["old_prince", "marya", "andrei", "bourienne", "julie"]},
    "2-3-26": {"gist": "仲夏安德烈自瑞士写信公布订婚，托玛丽雅试探父亲能否提前婚期；老公爵冷嘲拒绝，玛丽雅萌生出家云游之念又自斥有罪。", "tag": "peace", "place": "童山", "chars": ["marya", "andrei", "old_prince"]},
}
